NUM = re.compile(r"^[٠-٩0-9\s]+$")
os.makedirs(OUT, exist_ok=True)
def get(url, tries=4):
    err = None
    for i in range(tries):
        try:
            with urllib.request.urlopen(url, timeout=60) as r: return r.read()
        except Exception as e:
            err = e
    raise SystemExit("download failed: %s (%s)" % (url, err))
def page(n):
    d = json.loads(get(LAYOUT % n))
    prev = None
    for l in d["lines"]:
        if l["type"] == "text":
            ws = l["words"]
            while ws and prev is not None and NUM.match(ws[0]["word"]): prev["words"].append(ws.pop(0))
            if ws: prev = l
        elif l["type"] == "surah-header": prev = None
    out = []
    for l in d["lines"]:
        if l["type"] == "surah-header": out.append(["h", l.get("qpcV1") or l.get("text")])
        elif l["type"] == "basmala": out.append(["b", l["qpcV1"]])
        elif l["words"]:
            q = -1
            for w in l["words"]:
                if w["location"].endswith(":1") and w["location"][:-2] in QTR: q = QTR[w["location"][:-2]]; break
            out.append(["t", [[w["qpcV1"], int(w["location"].split(":")[0]), int(w["location"].split(":")[1])] for w in l["words"]], q])
    json.dump(out, open("%s/p%03d.json" % (OUT, n), "w", encoding="utf-8"), ensure_ascii=False, separators=(",", ":"))
    open("%s/QCF_P%03d.woff2" % (OUT, n), "wb").write(get(FONT % n))
with cf.ThreadPoolExecutor(8) as ex: list(ex.map(page, range(1, 605)))
for name, url in EXTRA.items(): open(OUT + "/" + name, "wb").write(get(url))
print("mushaf assets:", len(os.listdir(OUT)))
assert len(os.listdir(OUT)) == 1210
